// GERADO por scripts/build-workflows.mjs a partir de: src/flow-a/validate.js
// Edite os arquivos-fonte e rode "npm run build" — não edite este código na UI.

// Fluxo A — validação, normalização e chave de idempotência do payload de entrada.
// Este arquivo é embutido no Code node "Validate & Normalize" por scripts/build-workflows.mjs.
// Tudo abaixo do marcador "--- test exports ---" é removido no build.

const LIMITS = { message: 8000, subject: 120, name: 120, company: 160, source: 40 };
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const KINDS = ['lead', 'ticket'];

function cleanString(value, max) {
  if (value === undefined || value === null) return null;
  const s = String(value).replace(/\s+/g, ' ').trim();
  if (!s) return null;
  return max ? s.slice(0, max) : s;
}

function cleanMessage(value) {
  if (value === undefined || value === null) return null;
  // Preserva quebras de linha da mensagem, remove caracteres de controle
  const s = String(value).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim();
  return s ? s.slice(0, LIMITS.message) : null;
}

function normalizeInbound(body, nowIso) {
  const errors = [];
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { valid: false, errors: [{ field: 'body', message: 'JSON object esperado' }], lead: null };
  }

  const email = cleanString(body.email, 254);
  const emailNorm = email ? email.toLowerCase() : null;
  if (!emailNorm || !EMAIL_RE.test(emailNorm)) {
    errors.push({ field: 'email', message: 'e-mail ausente ou inválido' });
  }

  const message = cleanMessage(body.message);
  if (!message || message.length < 3) {
    errors.push({ field: 'message', message: 'mensagem obrigatória (mín. 3 caracteres)' });
  }

  const kindRaw = cleanString(body.kind, 20);
  const kind = kindRaw ? kindRaw.toLowerCase() : 'lead';
  if (!KINDS.includes(kind)) {
    errors.push({ field: 'kind', message: `kind deve ser um de: ${KINDS.join(', ')}` });
  }

  if (errors.length) return { valid: false, errors, lead: null };

  const name = cleanString(body.name, LIMITS.name);
  const [firstName, ...rest] = name ? name.split(' ') : [null];
  const subject = cleanString(body.subject, LIMITS.subject)
    || cleanString(message.split('\n')[0], LIMITS.subject);

  return {
    valid: true,
    errors: [],
    lead: {
      kind,
      source: (cleanString(body.source, LIMITS.source) || 'api').toLowerCase(),
      email: emailNorm,
      name,
      firstName: firstName || null,
      lastName: rest.length ? rest.join(' ') : null,
      company: cleanString(body.company, LIMITS.company),
      domain: emailNorm.split('@')[1],
      phone: cleanString(body.phone, 40),
      subject,
      message,
      metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata) ? body.metadata : {},
      receivedAt: nowIso,
    },
  };
}

function fnv1a64Hex(str) {
  // Fallback sem dependências caso o módulo crypto não esteja liberado no runner
  let h1 = 0x811c9dc5;
  let h2 = 0xcbf29ce4;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x01000193 ^ 0x5bd1e995) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

function hashString(str) {
  try {
    // eslint-disable-next-line global-require
    return require('crypto').createHash('sha256').update(str, 'utf8').digest('hex');
  } catch (e) {
    return fnv1a64Hex(str);
  }
}

function idempotencyKey(lead) {
  // Não inclui receivedAt: reenvios do mesmo formulário colapsam na mesma chave
  return hashString([lead.email, lead.kind, lead.subject || '', lead.message].join('|').toLowerCase());
}

// --- entrada do nó ---

const result = normalizeInbound($json.body, new Date().toISOString());
return {
  json: {
    ...result,
    idempotencyKey: result.valid ? idempotencyKey(result.lead) : null,
    payload: $json.body ?? null,
  },
};

// GERADO por scripts/build-workflows.mjs a partir de: src/flow-a/enrichment.js
// Edite os arquivos-fonte e rode "npm run build" — não edite este código na UI.

// Fluxo A — enriquecimento de empresa/contato.
// Heurística local sempre roda; API externa (opcional) apenas sobrescreve quando responde algo útil.
// Embutido nos Code nodes "Heuristic Enrichment" e "Merge Enrichment".

const FREE_EMAIL_DOMAINS = [
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'msn.com',
  'yahoo.com', 'yahoo.com.br', 'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com',
  'bol.com.br', 'uol.com.br', 'terra.com.br', 'ig.com.br', 'gmx.com', 'zoho.com',
];

const TLD_COUNTRY = { br: 'BR', pt: 'PT', ar: 'AR', mx: 'MX', es: 'ES', uk: 'GB', de: 'DE', fr: 'FR', it: 'IT', cl: 'CL', co: 'CO' };
const SECOND_LEVEL = ['com', 'net', 'org', 'gov', 'edu', 'co', 'ind', 'adv'];

function sizeTier(employees) {
  const n = Number(employees);
  if (!Number.isFinite(n) || n <= 0) return 'unknown';
  if (n >= 1000) return 'enterprise';
  if (n >= 200) return 'mid_market';
  return 'smb';
}

function companyFromDomain(domain) {
  const labels = domain.toLowerCase().split('.');
  // acme.com.br -> acme ; app.acme.io -> acme
  let idx = labels.length - 2;
  if (labels.length >= 3 && SECOND_LEVEL.includes(labels[labels.length - 2])) idx = labels.length - 3;
  const label = labels[Math.max(idx, 0)];
  return label
    .split(/[-_]/)
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function heuristicEnrichment(lead) {
  const domain = (lead.domain || '').toLowerCase();
  const isFreeEmail = FREE_EMAIL_DOMAINS.includes(domain);
  const tld = domain.split('.').pop();
  return {
    source: 'heuristic',
    domain,
    isFreeEmail,
    isCorporate: Boolean(domain) && !isFreeEmail,
    companyName: lead.company || (domain && !isFreeEmail ? companyFromDomain(domain) : null),
    industry: null,
    employees: null,
    sizeTier: 'unknown',
    country: TLD_COUNTRY[tld] || null,
    fallbackReason: null,
  };
}

function pick(obj, paths) {
  for (const p of paths) {
    const v = p.split('.').reduce((acc, k) => (acc && acc[k] !== undefined ? acc[k] : undefined), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
}

function mergeEnrichment(base, apiResponse) {
  if (!apiResponse || typeof apiResponse !== 'object') return { ...base };
  if (apiResponse.error) {
    const msg = typeof apiResponse.error === 'string' ? apiResponse.error : apiResponse.error.message;
    return { ...base, fallbackReason: `enrichment_api_error: ${msg || 'unknown'}` };
  }

  // Aceita formatos comuns (Clearbit, Apollo, PDL) sem acoplar a um fornecedor
  const name = pick(apiResponse, ['name', 'company.name', 'organization.name']);
  const industry = pick(apiResponse, ['category.industry', 'industry', 'organization.industry']);
  const employeesRaw = pick(apiResponse, ['metrics.employees', 'employees', 'employeeCount', 'organization.estimated_num_employees']);
  const country = pick(apiResponse, ['geo.countryCode', 'country', 'location.country_code']);
  if (!name && !industry && !employeesRaw) return { ...base };

  const employees = employeesRaw !== null && Number.isFinite(Number(employeesRaw)) ? Number(employeesRaw) : null;
  return {
    ...base,
    source: 'api',
    companyName: name || base.companyName,
    industry: industry || null,
    employees,
    sizeTier: sizeTier(employees),
    country: country ? String(country).toUpperCase().slice(0, 2) : base.country,
  };
}

// --- entrada do nó ---

const v = $('Validate & Normalize').first().json;
const cfg = $('Load Config').first().json.config;
const enrichment = heuristicEnrichment(v.lead);
return {
  json: {
    lead: v.lead,
    idempotencyKey: v.idempotencyKey,
    payload: v.payload,
    startedAt: v.lead.receivedAt,
    enrichment,
    useExternal: Boolean(cfg.enrichmentApiUrl) && enrichment.isCorporate,
    enrichmentUrl: cfg.enrichmentApiUrl,
  },
};

